  // src/interactors/circuits/hide-workout-exercise.ts
  function hideWorkoutExercise(gateways2, input) {
    const exercise = gateways2.exercises.find(input.exerciseId);
    const assignment = assignmentFor(input);
    if (!exercise || !assignment || assignment.exerciseId !== input.exerciseId || exercise.always_locked || assignment.fixed || gateways2.exercises.isDeleted(input.exerciseId))
      return unchanged();
    if (gateways2.exercises.isHidden(input.exerciseId))
      return toggleHiddenExercise(gateways2, { exerciseId: input.exerciseId });
    const wasLocked = assignment.locked;
    gateways2.exercises.hiddenIds().push(input.exerciseId);
    assignment.locked = false;
    const replaced = randomReplaceExercise(gateways2, {
      dayId: input.dayId,
      circuitIndex: input.circuitIndex,
      position: input.position
    });
    if (!replaced.value) {
      gateways2.exercises.replaceHiddenIds(
        gateways2.exercises.hiddenIds().filter((id) => id !== input.exerciseId)
      );
      assignment.locked = wasLocked;
      return {
        changed: true,
        refresh: ["all"],
        toast: {
          message: `${exercise.name} was kept because no replacement is available.`,
          tone: "error"
        }
      };
    }
    return {
      ...replaced,
      value: void 0,
      toast: {
        message: `${exercise.name} hidden. ${replaced.value.name} selected instead.`,
        tone: "success"
      }
    };
  }

  // src/interactors/circuits/move-circuit-exercise.ts
  function moveCircuitExercise(gateways2, input) {
    const circuit = gateways2.week.day(input.dayId).circuits[input.circuitIndex];
    const assignments = mainAssignments(circuit);
    const index = positionIndex(input.position);
    const nextIndex = index + input.direction;
    if (index < 0 || nextIndex < 0 || nextIndex >= assignments.length)
      return unchanged();
    [assignments[index], assignments[nextIndex]] = [
      assignments[nextIndex],
      assignments[index]
    ];
    markManualSetupTransitions(assignments);
    writeMainAssignments(circuit, assignments);
    syncCycleTemplateFromDay(input.dayId);
    resetCircuitCompletion(circuit);
    return changed({ refresh: ["all"] });
  }

  // src/interactors/circuits/remove-round-exercise.ts
