  // src/interactors/workout/stop-expired-workout-timer.ts
  function stopExpiredWorkoutTimer(gateways2, input) {
    const day = gateways2.week.day(input.dayId);
    if (!day || day.rest || !day.timer.startedAt) return unchanged();
    const duration = timerDuration(day);
    if (timerElapsed(day) < duration) return unchanged();
    day.timer.elapsedMs = duration;
    day.timer.startedAt = null;
    return changed();
  }

  // src/ui/save-indicator.ts
  function showSaveState() {
    const unsaved = gateways.saveStatus.hasUnsavedChanges();
    const marker = byId("save-state");
    if (marker) marker.hidden = !unsaved;
    byId("save-button")?.classList.toggle("has-unsaved-changes", unsaved);
  }
  var UNSAVED_CHANGES_WARNING = "You have changes that aren't saved to your workout file yet.";
  function confirmDiscardUnsavedChanges(action) {
    return !gateways.saveStatus.hasUnsavedChanges() || window.confirm(`${UNSAVED_CHANGES_WARNING} ${action} Continue?`);
  }

  // src/ui/session.ts
  function storeSession() {
    gateways.browserStorage.save(gateways.appState.current());
    gateways.saveStatus.markUnsaved();
    showSaveState();
  }

  // src/ui/timer-view.ts
  function timerDayId() {
    if (!DAY_CONFIG.some((day2) => day2.id === ui.currentView)) return null;
    const day = gateways.week.day(ui.currentView);
    return day && !day.rest ? ui.currentView : null;
  }
  function updateWorkoutTimer() {
    const timer = document.getElementById("workout-timer");
    const display = document.getElementById("timer-display");
    const toggle = byId("timer-toggle");
    const reset = byId("timer-reset");
    const subtract = byId("timer-minus");
    const add = byId("timer-plus");
    if (!timer || !display || !toggle || !reset || !subtract || !add) return;
    const dayId = timerDayId();
    timer.hidden = !dayId;
    if (!dayId) return;
    if (stopExpiredWorkoutTimer(gateways, { dayId }).changed) storeSession();
    const day = gateways.week.day(dayId);
    const duration = timerDuration(day);
    const elapsed = timerElapsed(day);
    const remaining = duration - elapsed;
    const warmupComplete = Object.values(day.preChecklist).every(Boolean);
    const workoutComplete = allRoundsComplete(day);
    const isRunning = Boolean(day.timer.startedAt);
    display.textContent = formatTimer(remaining);
    timer.setAttribute(
      "aria-label",
      `${duration / 6e4}-minute workout timer`
    );
    timer.classList.toggle("is-running", isRunning);
    timer.classList.toggle("is-expired", remaining <= 0 && !workoutComplete);
    toggle.textContent = isRunning ? "Pause" : elapsed > 0 ? "Resume" : "Start";
    toggle.disabled = !warmupComplete || workoutComplete || remaining <= 0;
    toggle.title = !warmupComplete ? "Complete the warm-up before starting the workout timer" : workoutComplete ? "All nine rounds are complete" : isRunning ? "Pause the workout timer" : elapsed > 0 ? "Resume the workout timer" : "Start the workout timer";
    reset.disabled = elapsed <= 0;
    subtract.disabled = isRunning || workoutComplete || duration <= MIN_WORKOUT_DURATION_MS || duration - TIMER_ADJUSTMENT_MS <= elapsed;
    add.disabled = isRunning || workoutComplete || duration >= MAX_WORKOUT_DURATION_MS;
    subtract.title = isRunning ? "Pause the timer before adjusting it" : "Remove five minutes";
    add.title = isRunning ? "Pause the timer before adjusting it" : "Add five minutes";
    const targetSummary = document.getElementById("timer-target-summary");
    const deadlineSummary = document.getElementById("timer-deadline-summary");
    if (targetSummary)
      targetSummary.textContent = `About ${duration / 6e4} minutes`;
    if (deadlineSummary)
      deadlineSummary.textContent = `The nine round deadlines scale evenly across your ${duration / 6e4}-minute workout after the warm-up.`;
    document.querySelectorAll?.(".round-check[data-global-round]").forEach((label) => {
      const globalRound = Number(label.dataset.globalRound);
      const circuit = day.circuits[Math.floor(globalRound / 3)];
      const checked = circuit?.roundsCompleted[globalRound % 3];
      label.classList.toggle(
        "is-overdue",
        !checked && elapsed >= roundDeadlineMs(day, globalRound)
      );
    });
  }

