  // src/ui/render.ts
  function render() {
    const complete = completedCircuits();
    const circuitTotal = enabledDays().length * 3;
    document.getElementById("week-number").textContent = `Week ${gateways.week.number()}`;
    document.getElementById("week-date").textContent = formatDate(
      gateways.week.startedAt()
    );
    document.getElementById("week-progress-label").textContent = `${complete} of ${circuitTotal} circuits complete`;
    document.getElementById("week-progress-bar").style.width = `${circuitTotal ? complete / circuitTotal * 100 : 0}%`;
    renderTabs();
    const workoutView = document.getElementById("workout-view");
    const libraryView = document.getElementById("library-view");
    const settingsView = document.getElementById("settings-view");
    const showingLibrary = ui.currentView === "library";
    const showingSettings = ui.currentView === "settings";
    workoutView.hidden = showingLibrary || showingSettings;
    libraryView.hidden = !showingLibrary;
    settingsView.hidden = !showingSettings;
    if (showingLibrary) renderLibrary();
    else if (showingSettings) renderSettings();
    else renderWorkout(ui.currentView);
    updateWorkoutTimer();
  }

  // src/ui/presenter.ts
  function dialogOpen(id) {
    return Boolean(document.getElementById(id)?.open);
  }
  function forgetStaleWorkoutPanes() {
    const week = gateways.week.current();
    if (ui.renderedWeek !== week) {
      ui.expandedActivators.clear();
      ui.renderedWeek = week;
    }
  }
  var REFRESHERS = {
    all: () => render(),
    settings: () => renderSettings(),
    tabs: () => renderTabs(),
    library: () => renderLibrary(),
    workout: ({ dayId }) => renderWorkout(dayId || ui.currentView),
    timer: () => updateWorkoutTimer(),
    "replacement-results": () => {
      if (dialogOpen("replace-dialog")) renderReplacementResults();
    },
    "favorite-results": () => {
      if (dialogOpen("favorite-dialog")) renderFavoriteResults();
    },
    "split-dialog": () => renderSplitDialog(),
    "equipment-dialog": () => renderEquipmentCatalogDialog()
  };
  function present(result, options = {}) {
    if (result.changed) storeSession();
    if (result.inSyncWithFile) {
      gateways.saveStatus.markSaved();
      showSaveState();
    }
    if (result.view) ui.currentView = result.view;
    if (result.fileStatus)
      setFileStatus(result.fileStatus.message, result.fileStatus.connected);
    forgetStaleWorkoutPanes();
    for (const target of result.refresh) REFRESHERS[target](options);
    if (result.toast) showToast(result.toast.message, result.toast.tone);
  }

