  // src/interactors/library/exercise-form.ts
  function normalizeExerciseForm(values) {
    const name = String(values.name || "").trim();
    const defaultReps = String(values.defaultReps || "10").trim() || "10";
    const measureType = values.measureType === "reps" || values.measureType === "seconds" ? values.measureType : /sec|second/i.test(defaultReps) ? "seconds" : "reps";
    const defaultLoad = String(values.defaultLoad || "").trim().slice(0, 40);
    const loadBasis = values.loadBasis === "total" || values.loadBasis === "each" ? values.loadBasis : "total";
    const selectedEquipment = normalizeEquipmentCatalog(values.equipmentVarieties);
    const equipmentVarieties = selectedEquipment.length ? selectedEquipment : ["Body weight"];
    const record = {
      name,
      aliases: normalizeExerciseAliases(values.aliases, name),
      category: String(values.category || "Other"),
      equipment: equipmentLabelFromVarieties(equipmentVarieties),
      equipmentVarieties,
      bodyParts: normalizeBodyParts(values.bodyParts),
      instructionUrl: String(values.instructionUrl || "").trim() || null,
      sourceRow: null,
      custom: true,
      movementPattern: String(values.movementPattern || "other"),
      movementRole: String(values.movementRole || "isolation"),
      forceType: String(values.forceType || "other"),
      defaultReps,
      effectivenessScore: clampRating(values.effectivenessScore, 3),
      shoulderCaution: values.shoulderCaution,
      backCaution: values.backCaution,
      totalBodyActivator: values.totalBodyActivator,
      bothSides: values.bothSides,
      notes: String(values.notes || "").trim() || null
    };
    return {
      name,
      record,
      equipmentVarieties,
      defaultReps,
      measureType,
      defaultLoad,
      loadBasis
    };
  }
  function saveExerciseDefaults(gateways2, exerciseId, form) {
    gateways2.preferences.replaceEquipmentCatalog(
      normalizeEquipmentCatalog([
        ...gateways2.preferences.equipmentCatalog(),
        ...form.equipmentVarieties,
        ...gateways2.exercises.find(exerciseId)?.equipment_varieties || []
      ])
    );
    const stats = gateways2.exercises.stats(exerciseId);
    if (stats.weight !== form.defaultLoad) stats.loadProgressCount = 0;
    stats.reps = cleanRepValue(form.defaultReps).slice(0, 40);
    stats.measureType = form.measureType;
    stats.weight = form.defaultLoad;
    stats.loadBasis = form.loadBasis;
    return stats;
  }

  // src/interactors/library/add-custom-exercise.ts
  function addCustomExercise(gateways2, input) {
    const form = normalizeExerciseForm(input);
    const exerciseId = idFor(form.name);
    if (!exerciseId || gateways2.exercises.has(exerciseId)) {
      const formError = "An exercise with that name already exists.";
      return failed(formError, { value: { formError } });
    }
    gateways2.exercises.customRecords().push(form.record);
    gateways2.exercises.rebuildCatalog(
      gateways2.exercises.customRecords(),
      gateways2.exercises.edits()
    );
    gateways2.exercises.stats(exerciseId);
    saveExerciseDefaults(gateways2, exerciseId, form);
    return changed({
      refresh: ["all"],
      toast: `${form.name} added to the exercise library.`,
      value: { exerciseId }
    });
  }

  // src/interactors/library/edit-exercise.ts
  function editExercise(gateways2, input) {
    const existing = gateways2.exercises.find(input.exerciseId);
    if (!existing) return unchanged();
    const previousEffectivenessScore = exerciseEffectivenessScore(existing);
    const form = normalizeExerciseForm(input.values);
    const edits = gateways2.exercises.edits();
    const previousEdit = edits[input.exerciseId];
    edits[input.exerciseId] = form.record;
    gateways2.exercises.rebuildCatalog(gateways2.exercises.customRecords(), edits);
    for (const day of DAY_CONFIG) {
      for (const circuit of gateways2.week.day(day.id).circuits) {
        markManualSetupTransitions(mainAssignments(circuit));
      }
    }
    const issues = validateWeek(gateways2.week.current());
    if (issues.length) {
      if (previousEdit) edits[input.exerciseId] = previousEdit;
      else delete edits[input.exerciseId];
      gateways2.exercises.rebuildCatalog(
        gateways2.exercises.customRecords(),
        edits
      );
      const formError = `That edit conflicts with the current plan: ${issues[0]}`;
      return failed(formError, { value: { formError } });
    }
    const stats = saveExerciseDefaults(gateways2, input.exerciseId, form);
    if (previousEffectivenessScore !== form.record.effectivenessScore) {
      stats.preference = 0;
      stats.effectivenessFeedbackBase = null;
    }
    return changed({
      refresh: ["all"],
      toast: `${form.name} updated.`,
      value: { exerciseId: input.exerciseId }
    });
  }

