  // src/interactors/files/save-workout-file.ts
  async function saveWorkoutFile(gateways2) {
    try {
      const outcome = await gateways2.workoutFile.write(
        JSON.stringify(exportPayload(), null, 2),
        { chooseIfMissing: true, requestPermission: true }
      );
      switch (outcome.status) {
        case "saved":
          return unchanged({
            toast: `Saved directly to ${outcome.fileName}.`,
            fileStatus: { message: `Saved \xB7 ${outcome.displayPath}`, connected: true },
            inSyncWithFile: true
          });
        case "unsupported":
          return failed(
            "Direct file saving requires a current Chrome or Edge browser. Your work is still kept in this browser."
          );
        case "permission-denied":
          return failed("Permission to write the workout file was not granted.");
        default:
          return unchanged();
      }
    } catch (error) {
      return failed(
        `The workout file could not be saved: ${error.message}`
      );
    }
  }

